#if canImport(AVFoundation)
import CoreImage
import CoreText
import ImageIO
import UniformTypeIdentifiers
import XCTest
@testable import KriaMediaEngine

/// KRI-1192: spoken captions in pt, es, el, de, ko, it, fr, ar, da and sr draw on the phone (live preview and
/// export share this painter) with every letter in ONE bundled face: the face the server rule picks
/// (`tests/fixtures/caption-glyph-parity/script_fallback_faces.json`, generated by
/// `font_coverage.glyph_safe_family`), never a system fallback. Arabic draws right to left with joined letters,
/// and its highlighted word sweeps from the right.
///
/// Failure modes (docs/reviews/kri-1192-caption-languages.md): F6 missing glyphs (boxes, or a word in two
/// faces), F7 Arabic left to right / unjoined / highlight sweeping the wrong way, F11 iPhone and cloud picking
/// different faces, F15 English or Turkish changing.
///
/// Set `KRIA_CAPTION_VERIFY_DIR` to write every rendered caption as a PNG plus a labelled `montage.png` there.
final class CaptionScriptRenderTests: XCTestCase {
    private static let repo: URL = {
        let path = #filePath
        let root = path.range(of: "/src/apps/ios/")!
        return URL(fileURLWithPath: String(path[..<root.lowerBound]))
    }()
    private let canvas = CGSize(width: 1080, height: 1920)
    private let white = TextInk(red: 1, green: 1, blue: 1, alpha: 1)
    private let lime = TextInk(red: 0xC5 / 255.0, green: 0xF8 / 255.0, blue: 0x2A / 255.0, alpha: 1)

    private struct Parity: Decodable {
        struct Text: Decodable { let id: String; let language: String; let text: String }
        let texts: [Text]
        let faces: [String: [String: String]]
    }

    private func parity() throws -> Parity {
        try JSONDecoder().decode(Parity.self, from: Data(contentsOf: Self.repo
            .appendingPathComponent("tests/fixtures/caption-glyph-parity/script_fallback_faces.json")))
    }

    /// Registry family -> font file, as the server reads it.
    private func registryFiles() throws -> [String: String] {
        let url = Self.repo.appendingPathComponent("src/apps/api/assets/fonts/font-registry.json")
        let registry = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        let fonts = try XCTUnwrap(registry["fonts"] as? [String: [String: Any]])
        return fonts.compactMapValues { $0["file"] as? String }
    }

    private func fontURL(_ file: String) -> URL {
        Self.repo.appendingPathComponent("src/apps/api/assets/fonts/" + file)
    }

    /// The face the server draws `textID` in when the creator picked `family`.
    private func face(_ family: String, _ textID: String, parity: Parity, files: [String: String]) throws -> (name: String, url: URL) {
        let name = parity.faces[textID]?[family] ?? family
        return (name, fontURL(try XCTUnwrap(files[name], name)))
    }

    /// The phone caption look (`NativeEditorRenderCompiler`'s default caption style).
    private func style(color: TextInk) -> AuthoredTextLayout.Style {
        .init(fontAssetID: "font", size: 78, widthFraction: 920.0 / 1080, xFraction: 0.5, yFraction: 0.82, color: color,
              stroke: .init(red: 0, green: 0, blue: 0, alpha: 1), strokeWidth: 4,
              shadows: [TextBlurLayer(color: .init(red: 0, green: 0, blue: 0, alpha: 0.5), sigma: 0, dx: 1, dy: 1)],
              bottomAligned: true)
    }

    private func layer(_ text: String, font: URL) throws -> PortableTextLayer {
        try AuthoredTextLayout.compile(id: "caption", text: text, start: 0, end: 2, style: style(color: white),
                                       fontURL: font, canvas: Canvas(width: Int(canvas.width), height: Int(canvas.height)))
    }

    private struct Painted { let image: CGImage; let frame: CGRect }

    private func paint(_ layer: PortableTextLayer, font: URL) throws -> Painted {
        let painter = try PortableTextVectorPainter(layer: layer, assetURLs: ["font": font], canvas: canvas)
        let image = try painter.image(maxBitmapBytes: 64 * 1024 * 1024)
        return Painted(image: try XCTUnwrap(CIContext().createCGImage(image, from: image.extent)), frame: painter.bounds)
    }

    private func karaokeFrame(_ layer: PortableTextLayer, font: URL, at time: Double) throws -> Painted {
        let made = try RecipeTextLayer.make(layer, assetURLs: ["font": font], canvas: canvas)
        let image = try XCTUnwrap(made.karaoke).image(localTime: time)
        return Painted(image: try XCTUnwrap(CIContext().createCGImage(image, from: image.extent)), frame: made.frame)
    }

    private func rgba(_ image: CGImage) -> [UInt8] {
        var bytes = [UInt8](repeating: 0, count: image.width * image.height * 4)
        let context = CGContext(data: &bytes, width: image.width, height: image.height, bitsPerComponent: 8,
                                bytesPerRow: image.width * 4, space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
        context.draw(image, in: CGRect(x: 0, y: 0, width: image.width, height: image.height))
        return bytes
    }

    /// Canvas x of every pixel matching `match` (r, g, b, a premultiplied).
    private func columns(_ painted: Painted, where match: (UInt8, UInt8, UInt8, UInt8) -> Bool) -> [Double] {
        let bytes = rgba(painted.image)
        var xs: [Double] = []
        for index in stride(from: 0, to: bytes.count, by: 4) where match(bytes[index], bytes[index + 1], bytes[index + 2], bytes[index + 3]) {
            xs.append(painted.frame.minX + Double((index / 4) % painted.image.width))
        }
        return xs
    }

    private func whiteInk(_ painted: Painted) -> [Double] { columns(painted) { r, g, b, a in a > 200 && r > 200 && g > 200 && b > 200 } }
    private func limeInk(_ painted: Painted) -> [Double] { columns(painted) { r, g, b, a in a > 200 && g > 200 && r > 150 && b < 110 } }
    private func mean(_ values: [Double]) -> Double { values.reduce(0, +) / Double(max(1, values.count)) }

    private static let languages = ["pt-0", "es-0", "el-0", "de-0", "ko-0", "it-0", "fr-0", "ar-0", "da-0", "sr-0", "sr-latn-0", "en-0", "tr-0"]

    // MARK: - F6 / F11 / F15: each language draws in the server's face, ink present, nothing falls back

    func testEveryCaptionLanguageDrawsInTheServersCoveringFace() throws {
        let parity = try parity(), files = try registryFiles()
        let texts = Dictionary(uniqueKeysWithValues: parity.texts.map { ($0.id, $0.text) })
        var rows: [(String, Painted)] = []
        for family in ["TikTok Sans", "Montserrat", "Poppins Bold"] {
            for id in Self.languages {
                let text = try XCTUnwrap(texts[id], id)
                let face = try face(family, id, parity: parity, files: files)
                let painted: Painted
                do {
                    painted = try paint(try layer(text, font: face.url), font: face.url)
                } catch {
                    XCTFail("\(id) in \(family) -> \(face.name) failed to draw: \(error)"); continue
                }
                let ink = whiteInk(painted).count
                XCTAssertGreaterThan(ink, 4000, "\(id) in \(face.name) drew almost nothing (\(ink) px)")
                rows.append(("\(id) · \(family) → \(face.name)", painted))
            }
        }
        // English and Turkish never leave the creator's face (F15).
        for id in ["en-0", "tr-0"] {
            for family in ["TikTok Sans", "Montserrat", "Poppins Bold"] {
                XCTAssertNil(parity.faces[id]?[family], "\(id) must keep \(family)")
            }
        }
        // Greek all caps (the Greek rule drops accents) still draws in TikTok Sans.
        let greek = try XCTUnwrap(texts["el-0"]).uppercased(with: Locale(identifier: "el"))
        let tiktok = try face("TikTok Sans", "el-0", parity: parity, files: files)
        rows.append(("el-0 ALL CAPS · TikTok Sans", try paint(try layer(greek, font: tiktok.url), font: tiktok.url)))
        let (arabicRows, _) = try arabicKaraokeFrames()
        rows.append(contentsOf: arabicRows)
        try writeEvidence(rows)
    }

    /// The guard that keeps a word from mixing faces: the default face (no Hangul, no Arabic) and a Latin-only
    /// face (no Greek) refuse to draw these scripts instead of borrowing a system face. This is why the rule
    /// above must swap the WHOLE run.
    func testALatinFaceRefusesOtherScriptsInsteadOfBorrowingASystemFace() throws {
        let parity = try parity(), files = try registryFiles()
        let texts = Dictionary(uniqueKeysWithValues: parity.texts.map { ($0.id, $0.text) })
        for (family, id) in [("TikTok Sans", "ar-0"), ("TikTok Sans", "ko-0"), ("Montserrat", "el-0"), ("Montserrat", "ko-0"), ("Poppins Bold", "sr-0")] {
            let url = fontURL(try XCTUnwrap(files[family]))
            XCTAssertThrowsError(try layer(try XCTUnwrap(texts[id]), font: url), "\(id) in \(family)") { error in
                XCTAssertTrue((error as? NativePreviewFeatureError)?.feature.hasPrefix("font-fallback") == true, "\(error)")
            }
            XCTAssertNotNil(parity.faces[id]?[family], "the server swaps \(family) for \(id)")
        }
    }

    // MARK: - F7: Arabic right to left, joined, highlight sweeping from the right

    /// A short Arabic cue that fits one line (four words), as the highlighted-word caption path compiles it.
    private func arabicCue() throws -> (words: [String], layer: PortableTextLayer, font: URL) {
        let parity = try parity(), files = try registryFiles()
        let sentence = try XCTUnwrap(parity.texts.first { $0.id == "ar-0" }?.text)
        let words = Array(sentence.split(separator: " ").prefix(4).map(String.init))
        let font = try face("TikTok Sans", "ar-0", parity: parity, files: files).url
        let starts = words.indices.map { Double($0) * 0.4 }
        let layer = try AuthoredTextLayout.compileHighlightedWords(id: "caption", text: words.joined(separator: " "),
            start: 0, end: 2.4, starts: starts, highlight: lime, style: style(color: white), fontURL: font,
            canvas: Canvas(width: Int(canvas.width), height: Int(canvas.height)))
        return (words, layer, font)
    }

    private func arabicKaraokeFrames() throws -> ([(String, Painted)], [Painted]) {
        let cue = try arabicCue()
        let starts = try XCTUnwrap(cue.layer.karaoke).starts
        let frames = try [0, 2, starts.count - 1].map { try karaokeFrame(cue.layer, font: cue.font, at: starts[$0] + 0.05) }
        let rows = zip(["first", "third", "last"], frames).map { ("ar highlighted · \($0.0) word lit", $0.1) }
        return (rows, frames)
    }

    func testArabicHighlightedWordsRunRightToLeftWithJoinedLetters() throws {
        let cue = try arabicCue()
        XCTAssertEqual(cue.layer.runs.map(\.text), cue.words, "runs stay in reading (logical) order")
        let graphics = try XCTUnwrap(CGDataProvider(url: cue.font as CFURL).flatMap(CGFont.init))
        let font = CTFontCreateWithGraphicsFont(graphics, cue.layer.runs[0].fontSize, nil, nil)
        func inkRange(_ run: PositionedTextRun) throws -> ClosedRange<Double> {
            let glyphs = try XCTUnwrap(run.glyphs, run.text)
            var ids = glyphs.map { CGGlyph($0.glyphID) }
            var boxes = [CGRect](repeating: .zero, count: ids.count)
            CTFontGetBoundingRectsForGlyphs(font, .default, &ids, &boxes, ids.count)
            let xs = zip(glyphs, boxes).flatMap { [run.x + $0.0.x + $0.1.minX, run.x + $0.0.x + $0.1.maxX] }
            return try XCTUnwrap(xs.min())...XCTUnwrap(xs.max())
        }
        let ranges = try cue.layer.runs.map(inkRange)
        for index in ranges.indices.dropLast() {
            XCTAssertGreaterThan(ranges[index].lowerBound, ranges[index + 1].upperBound - 1,
                                 "word \(index) (\(cue.words[index])) sits right of word \(index + 1)")
        }
        // Joined: each multi-letter word uses at least one contextual (initial/medial/final) form, not only the
        // isolated letters a per-character layout would place.
        for run in cue.layer.runs where run.text.count > 1 {
            var units = Array(run.text.utf16)
            var nominal = [CGGlyph](repeating: 0, count: units.count)
            XCTAssertTrue(CTFontGetGlyphsForCharacters(font, &units, &nominal, units.count))
            let shaped = Set(try XCTUnwrap(run.glyphs).map { CGGlyph($0.glyphID) })
            XCTAssertFalse(shaped.isSubset(of: Set(nominal)), "\(run.text) is drawn with isolated letters")
        }
        // Painted: the lit word moves from the right edge to the left as the cue plays.
        let (_, frames) = try arabicKaraokeFrames()
        let lit = frames.map { mean(limeInk($0)) }, rest = frames.map { mean(whiteInk($0)) }
        XCTAssertTrue(frames.allSatisfy { limeInk($0).count > 500 }, "a word is lit in every frame")
        XCTAssertGreaterThan(lit[0], rest[0], "the first word is lit on the right")
        XCTAssertLessThan(lit[2], rest[2], "the last word is lit on the left")
        XCTAssertGreaterThan(lit[0], lit[1])
        XCTAssertGreaterThan(lit[1], lit[2])
    }

    /// The full caption line (a shaped text run drawn by CoreText) also reads right to left: its ink spans the
    /// same columns as the word-by-word layer, so the first word is at the right end.
    func testArabicCaptionLineMatchesTheWordLayout() throws {
        let cue = try arabicCue()
        let line = try paint(try layer(cue.words.joined(separator: " "), font: cue.font), font: cue.font)
        let first = try karaokeFrame(cue.layer, font: cue.font, at: 0.05)
        let lineInk = whiteInk(line), firstWord = limeInk(first)
        XCTAssertGreaterThan(lineInk.count, 4000)
        // The first logical word's ink lies inside the line's rightmost quarter.
        let right = try XCTUnwrap(lineInk.max()), left = try XCTUnwrap(lineInk.min())
        XCTAssertGreaterThan(mean(firstWord), right - (right - left) / 4, "the first word is drawn at the right end")
    }

    // MARK: - F16: an older build never gets a face it does not bundle

    /// A recipe whose text draws in a script-fallback face derives `scriptFonts` (mirror of `EditRecipeV2`), so the
    /// device gate refuses it unless the server verified the token; the same caption in TikTok Sans does not.
    func testARunInAScriptFallbackFaceRequiresScriptFonts() throws {
        let files = try registryFiles()
        func recipe(_ file: String) throws -> EditRecipe {
            let fingerprint = try SHA256Fingerprinter().fingerprint(file: fontURL(file))
            let run = PositionedTextRun(text: "مرحبا", fontAssetID: "font-" + file, fontSize: 78, x: 100, baselineY: 1600,
                                        letterSpacing: 0, shaped: true, fill: white, stroke: white, strokeWidth: 0)
            return EditRecipe(schemaVersion: 2, rendererVersion: "kria-ios-2",
                assets: [MediaAsset(id: "font-" + file, relativePath: "font-" + file, fingerprint: fingerprint)],
                assetManifest: RenderAssetManifest(assets: [RenderAssetReference(id: "font-" + file,
                    fingerprint: try RenderFingerprint(fingerprint), source: .library(catalog: .font, catalogID: file, generation: fingerprint.hex))]),
                textLayers: [PortableTextLayer(id: "caption", start: 0, end: 1, anchorX: 540, anchorY: 1600, rotationDegrees: 0, runs: [run])])
        }
        let scriptFiles = try ["Noto Sans KR", "Noto Sans KR Bold", "Noto Sans Arabic", "Noto Sans Arabic Bold"].map { try XCTUnwrap(files[$0]) }
        XCTAssertEqual(Set(scriptFiles), EditRecipe.scriptFontFiles, "the registry's script_fallback files")
        for file in scriptFiles {
            let derived = try recipe(file).effectiveCapabilities
            XCTAssertTrue(derived.contains(.scriptFonts), file)
            let older = CapabilityNegotiator(provider: DefaultRendererCapabilities(capabilities: derived.subtracting([.scriptFonts])))
            XCTAssertEqual(older.decide(for: try recipe(file)).missingCapabilities, [.scriptFonts], file)
        }
        XCTAssertFalse(try recipe(try XCTUnwrap(files["TikTok Sans"])).effectiveCapabilities.contains(.scriptFonts))
    }

    // MARK: - Text the caption box cannot break or the face cannot space

    /// F9: a German compound wider than the caption box ("Unabhängigkeitserklärung" at 78 px is wider than
    /// 920 px) must stay one word in a highlighted caption. CoreText's line breaker splits such a word between
    /// two lines, and the word-by-word layer then refused the whole preview. The cloud keeps a word whole on
    /// its own row (`_wrap_word_indices`).
    func testALongCompoundStaysOneWordInAHighlightedCaption() throws {
        let parity = try parity(), files = try registryFiles()
        let text = try XCTUnwrap(parity.texts.first { $0.id == "de-2" }?.text)
        let words = text.split(whereSeparator: \.isWhitespace).map(String.init)
        let font = fontURL(try XCTUnwrap(files["TikTok Sans"]))
        let karaoke = try AuthoredTextLayout.compileHighlightedWords(id: "caption", text: text, start: 0, end: 9,
            starts: words.indices.map { Double($0) * 0.3 }, highlight: lime, style: style(color: white), fontURL: font,
            canvas: Canvas(width: Int(canvas.width), height: Int(canvas.height)))
        XCTAssertEqual(karaoke.runs.map(\.text), words)
        let compound = try XCTUnwrap(karaoke.runs.first { $0.text.hasPrefix("Unabhängigkeitserklärung") })
        let row = karaoke.runs.filter { $0.baselineY == compound.baselineY }
        XCTAssertEqual(row.map(\.text), [compound.text], "the compound gets a row of its own")
        let painted = try karaokeFrame(karaoke, font: font, at: 0.05)
        XCTAssertGreaterThanOrEqual(painted.frame.minX, 0, "and stays on the canvas")
        XCTAssertLessThanOrEqual(painted.frame.maxX, canvas.width)
        // A word that fits keeps today's layout exactly (the plain line breaker's rows, same size).
        let short = "Für die besten Aussichten auf Hongkong sollten Sie die Insel verlassen"
        let shortWords = short.split(separator: " ").map(String.init)
        let plain = try layer(short, font: font)
        let highlighted = try AuthoredTextLayout.compileHighlightedWords(id: "caption", text: short, start: 0, end: 4,
            starts: shortWords.indices.map { Double($0) * 0.3 }, highlight: lime, style: style(color: white), fontURL: font,
            canvas: Canvas(width: Int(canvas.width), height: Int(canvas.height)))
        XCTAssertEqual(Set(highlighted.runs.map(\.baselineY)), Set(plain.runs.map(\.baselineY)))
        XCTAssertEqual(highlighted.runs.first?.fontSize, 78)
    }

    /// French typography puts a thin space inside « » (FLEURS fr-1: "qu’«\u{2009}on"). Poppins Bold has no glyph
    /// for U+2009, so CoreText borrowed a system face for it and the caption refused to draw. A space separator
    /// the face lacks now draws as an ordinary space; a face that has it keeps it.
    func testASpaceTheFaceLacksDrawsAsAnOrdinarySpace() throws {
        let parity = try parity(), files = try registryFiles()
        let text = try XCTUnwrap(parity.texts.first { $0.id == "fr-1" }?.text)
        XCTAssertTrue(text.contains("\u{2009}"))
        let poppins = fontURL(try XCTUnwrap(files["Poppins Bold"]))
        let french = try layer(text, font: poppins)
        XCTAssertFalse(french.runs.contains { $0.text.contains("\u{2009}") })
        XCTAssertGreaterThan(whiteInk(try paint(french, font: poppins)).count, 4000)
        // A face with a thin space keeps the creator's character.
        let inter = fontURL(try XCTUnwrap(files["Inter"]))
        let graphics = try XCTUnwrap(CGDataProvider(url: inter as CFURL).flatMap(CGFont.init))
        var thin: [UniChar] = [0x2009], glyph: [CGGlyph] = [0]
        if CTFontGetGlyphsForCharacters(CTFontCreateWithGraphicsFont(graphics, 20, nil, nil), &thin, &glyph, 1) {
            XCTAssertTrue(try layer("a\u{2009}b", font: inter).runs.contains { $0.text.contains("\u{2009}") })
        }
    }

    /// Wire contract for the server's device recipe: a right-to-left word may arrive as a shaped TEXT run
    /// (`shaped: true`, `glyphs: nil`, `x` = the word's left edge) in an `activeOnly` karaoke layer, and the
    /// painter draws it exactly like the glyph runs the editor emits. Legacy (non-activeOnly) karaoke keeps
    /// requiring glyph runs (`KaraokeContent.validate`).
    func testServerShapedTextRunsPaintLikeTheEditorsGlyphRuns() throws {
        let cue = try arabicCue()
        let graphics = try XCTUnwrap(CGDataProvider(url: cue.font as CFURL).flatMap(CGFont.init))
        let font = CTFontCreateWithGraphicsFont(graphics, cue.layer.runs[0].fontSize, nil, nil)
        let textRuns = try cue.layer.runs.map { run -> PositionedTextRun in
            // The standalone word's own line starts where its leftmost glyph sits in the full line.
            let line = CTLineCreateWithAttributedString(NSAttributedString(string: run.text,
                attributes: [NSAttributedString.Key(kCTFontAttributeName as String): font,
                             NSAttributedString.Key(kCTKernAttributeName as String): 0]))
            var standalone: [CGFloat] = []
            for item in CTLineGetGlyphRuns(line) as! [CTRun] {
                var points = [CGPoint](repeating: .zero, count: CTRunGetGlyphCount(item))
                CTRunGetPositions(item, CFRange(location: 0, length: 0), &points)
                standalone += points.map(\.x)
            }
            let left = try XCTUnwrap(run.glyphs?.map(\.x).min())
            return PositionedTextRun(text: run.text, fontAssetID: run.fontAssetID, fontSize: run.fontSize,
                x: run.x + left - Double(try XCTUnwrap(standalone.min())), baselineY: run.baselineY, letterSpacing: 0, shaped: true,
                fill: run.fill, stroke: run.stroke, strokeWidth: run.strokeWidth, blurLayers: run.blurLayers)
        }
        let karaoke = try XCTUnwrap(cue.layer.karaoke)
        let server = PortableTextLayer(id: "caption", start: cue.layer.start, end: cue.layer.end, anchorX: cue.layer.anchorX,
            anchorY: cue.layer.anchorY, rotationDegrees: 0, runs: textRuns, effect: .karaokeLine, karaoke: karaoke)
        let decoded = try RecipeJSON.decoder().decode(PortableTextLayer.self, from: RecipeJSON.encoder().encode(server))
        try XCTUnwrap(decoded.karaoke).validate(runs: decoded.runs)
        for time in [0.05, 0.85, 1.65] {
            let editor = try karaokeFrame(cue.layer, font: cue.font, at: time)
            let wire = try karaokeFrame(decoded, font: cue.font, at: time)
            let a = limeInk(editor), b = limeInk(wire)
            XCTAssertGreaterThan(b.count, 500)
            XCTAssertEqual(mean(a), mean(b), accuracy: 6, "lit word at \(time)s sits in the same place")
            XCTAssertEqual(Double(a.count), Double(b.count), accuracy: Double(a.count) * 0.08)
        }
        // Not activeOnly: shaped runs stay refused (the legacy cumulative sweep paints glyph runs only).
        XCTAssertThrowsError(try KaraokeContent(starts: karaoke.starts, highlight: karaoke.highlight).validate(runs: textRuns))
    }

    // MARK: - Evidence

    private func writeEvidence(_ rows: [(String, Painted)]) throws {
        guard let path = ProcessInfo.processInfo.environment["KRIA_CAPTION_VERIFY_DIR"], !path.isEmpty else { return }
        let directory = URL(fileURLWithPath: path, isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let background = CGColor(red: 0.10, green: 0.14, blue: 0.25, alpha: 1)
        var bands: [(String, CGImage)] = []
        for (label, painted) in rows {
            // The caption band: full canvas width, the text's rows plus a margin.
            let height = Int(painted.frame.height) + 40
            let context = try XCTUnwrap(CGContext(data: nil, width: Int(canvas.width), height: height, bitsPerComponent: 8,
                bytesPerRow: 0, space: CGColorSpace(name: CGColorSpace.sRGB)!, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue))
            context.setFillColor(background); context.fill(CGRect(x: 0, y: 0, width: Int(canvas.width), height: height))
            context.draw(painted.image, in: CGRect(x: painted.frame.minX, y: 20, width: painted.frame.width, height: painted.frame.height))
            let band = try XCTUnwrap(context.makeImage())
            let name = label.components(separatedBy: CharacterSet.alphanumerics.inverted).filter { !$0.isEmpty }.joined(separator: "-")
            try writePNG(band, to: directory.appendingPathComponent(name + ".png"))
            bands.append((label, band))
        }
        let scale = 0.5, labelWidth = 330.0, gap = 6.0
        let width = labelWidth + canvas.width * scale
        let height = bands.reduce(0) { $0 + Double($1.1.height) * scale + gap }
        let montage = try XCTUnwrap(CGContext(data: nil, width: Int(width), height: Int(height), bitsPerComponent: 8, bytesPerRow: 0,
            space: CGColorSpace(name: CGColorSpace.sRGB)!, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue))
        montage.setFillColor(CGColor(gray: 0.06, alpha: 1)); montage.fill(CGRect(x: 0, y: 0, width: width, height: height))
        let labelFont = CTFontCreateWithName("Helvetica" as CFString, 15, nil)
        var top = height
        for (label, band) in bands {
            let bandHeight = Double(band.height) * scale
            top -= bandHeight
            montage.draw(band, in: CGRect(x: labelWidth, y: top, width: canvas.width * scale, height: bandHeight))
            let line = CTLineCreateWithAttributedString(NSAttributedString(string: label, attributes: [
                NSAttributedString.Key(kCTFontAttributeName as String): labelFont,
                NSAttributedString.Key(kCTForegroundColorAttributeName as String): CGColor(gray: 1, alpha: 1)]))
            montage.textPosition = CGPoint(x: 8, y: top + bandHeight / 2 - 5)
            CTLineDraw(line, montage)
            top -= gap
        }
        try writePNG(try XCTUnwrap(montage.makeImage()), to: directory.appendingPathComponent("montage.png"))
    }

    private func writePNG(_ image: CGImage, to url: URL) throws {
        let destination = try XCTUnwrap(CGImageDestinationCreateWithURL(url as CFURL, UTType.png.identifier as CFString, 1, nil))
        CGImageDestinationAddImage(destination, image, nil)
        XCTAssertTrue(CGImageDestinationFinalize(destination))
    }
}
#endif
